  if(t.dataset.dist){m.districts=m.districts||[];var j=m.districts.indexOf(t.dataset.dist);if(t.checked&&j<0)m.districts.push(t.dataset.dist);if(!t.checked&&j>-1)m.districts.splice(j,1);return}
  if(t.dataset.city){var i=m.cities.indexOf(t.dataset.city);if(t.checked&&i<0)m.cities.push(t.dataset.city);if(!t.checked&&i>-1)m.cities.splice(i,1);return}
  if(t.id==='fph'&&t.files[0]){sync(tb);FV.imgData(t.files[0],256).then(function(u){m.photo=u;formHtml(tb,redraw)},function(){BA.toast('Choose a picture file')})}
