 if(!RX.test(m.emerg))e.push('Emergency contact number must be 10 digits.');else if(m.emerg===m.phone)e.push('The emergency contact must be a different number from the staff member’s own.');
 if(!/^\S+@\S+\.\S+$/.test(m.personal))e.push('Enter a valid personal email address.');
 if(!dobOk(m.dob))e.push('Enter a date of birth. Staff must be at least 18.');
