 if(m.role==='field'){if(!m.cities.length)e.push('Choose at least one city for the field engineer.');if(!(m.districts||[]).length)e.push('Choose at least one district for the field engineer.');if(!m.manager)e.push('Choose the District Sales Manager this engineer reports to.');else{var mg=FV.get(m.manager);if(!mg||mg.role!=='dsm'||mg.state!==m.state)e.push('The engineer must report to a District Sales Manager in '+m.state+'.');else if((m.districts||[]).some(function(d){return (mg.districts||[]).indexOf(d)<0}))e.push('Every district must be one that '+mg.name+' oversees ('+(mg.districts||[]).join(', ')+').')}}
 if(m.role==='dsm'){if(!(m.districts||[]).length)e.push('Choose at least one district for the District Sales Manager.');if(!m.manager)e.push('Choose the Circle Manager this person reports to.');else{var cg=FV.get(m.manager);if(!cg||cg.role!=='circle'||cg.state!==m.state)e.push('The Circle Manager must be in '+m.state+'.')}}
 if(m.role==='lawyer'&&!m.advocate)e.push('Choose the advocate profile this login belongs to.');
